     InProgress(ReqId),
     Response(ReqId),
 }

 impl SlotState {
     pub open spec fn get_ReqId(&self) -> ReqId {
         match self {
             SlotState::Empty => arbitrary(),
             SlotState::Request(reqid) => *reqid,
             SlotState::InProgress(reqid) => *reqid,
             SlotState::Response(reqid) => *reqid,
         }
     }
 }

